(function addOfficialDuelCollections() {
  if (typeof FIGURES_DB === "undefined") return;
  const have = new Set(FIGURES_DB.map((f) => f.id));
  OFFICIAL_DUEL_NEW_FIGURES.forEach((nf) => {
    if (have.has(nf.id)) return;
    FIGURES_DB.push(Object.assign({}, nf, { wheel: nf.wheel.map((s) => Object.assign({}, s)) }));
  });
  if (typeof AUTHENTIC_FIG_SPRITES === "undefined") return;
  Object.keys(OFFICIAL_DUEL_NEW_SPRITES).forEach((key) => {
    AUTHENTIC_FIG_SPRITES[key] = Object.assign({}, OFFICIAL_DUEL_NEW_SPRITES[key]);
    if (typeof loadedFigImages === "undefined" || Object.prototype.hasOwnProperty.call(loadedFigImages, key)) return;
    let im = null;
    Object.defineProperty(loadedFigImages, key, {
      configurable: true, enumerable: true,
      get() { if (!im) { im = new Image(); im.src = OFFICIAL_DUEL_NEW_SPRITES[key].uri; } return im; },
      set(v) { im = v; }
    });
  });
})();

// Deoxys: cada forma com o próprio nome (v705). 218 = Speed, 219 = Normal, 224 = Attack, 229 = Defense
(function fixDeoxysNames() {
  if (typeof FIGURES_DB === "undefined") return;
  const N = { 218: "Deoxys Speed Forme", 219: "Deoxys", 224: "Deoxys Attack Forme", 229: "Deoxys Defense Forme" };
  const seen = {};
  FIGURES_DB.forEach((f) => {
    if (!/deoxys/i.test(f.name) || !N[f.officialDuelId]) return;
    const base = N[f.officialDuelId];
    f.name = seen[base] ? base + " (Nº" + f.officialDuelId + ")" : base;
    seen[base] = true;
  });
})();
